problems.solution:
def predict(m, b, x):
    return m * x + b


def mse(m, b, xs, ys):
    return sum((predict(m, b, x) - y) ** 2 for x, y in zip(xs, ys)) / len(xs)


def nudge(m, b, xs, ys, step):
    candidates = [(m, b), (m + step, b), (m - step, b), (m, b + step), (m, b - step)]
    return min(candidates, key=lambda c: mse(c[0], c[1], xs, ys))


def fit(xs, ys, steps, step):
    m, b = 0, 0
    for _ in range(steps):
        m, b = nudge(m, b, xs, ys, step)
    return (m, b)
